        let rec = record_for(key, "id", 1, &[" a ", "x\ny"]);
        assert!(matches!(
            verify_input(rec.as_bytes(), key, Some(&expect(&[" a ", "x\ny"]))),
            VerifyOutcome::Valid
        ));
    }

